Send Cash Transfer To Beneficiary.code:
// Pay a cash transfer to a beneficiary's mobile money wallet.
// The API response is added to state.references.
createPayment({
  phonenumber: $.data.phone, // international format, e.g. '+256700000000'
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  amount: String($.data.amount), // sent as a string, e.g. '50000'
  currency: 'UGX',
  description: 'Monthly cash transfer',
  payment_type: 'money',
  // Your own ids travel with the payment and come back in callbacks.
  metadata: { beneficiaryId: $.data.beneficiaryId, cycle: $.data.cycle },
});

Pay Health Worker Stipend With Callback.code:
// Pay a community health worker stipend and get status updates via callback.
createPayment({
  phonenumber: $.data.phone,
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  amount: '150000',
  currency: 'UGX',
  description: `CHW stipend ${$.data.month}`,
  callback_url: 'https://app.openfn.org/i/<your-webhook-id>',
  send_sms_message: true, // notify the recipient by SMS
  metadata: { chwId: $.data.chwId },
});

Register Contact.code:
// Register a beneficiary as a Beyonic contact.
createContact({
  first_name: $.data.firstName,
  last_name: $.data.lastName,
  phone_number: $.data.phone, // required, e.g. '+256700000000'
  email: $.data.email,
  type: 'beneficiary',
  metadata: { householdId: $.data.householdId },
});

Request Mobile Money Collection.code:
// Request a savings-group or insurance contribution from a member.
createCollectionRequest({
  phonenumber: $.data.phone, // required
  amount: String($.data.amount), // required, e.g. '3000'
  currency: 'UGX', // required
  reason: 'Community health insurance premium',
  send_instructions: true, // text the payer instructions on how to pay
  success_message: 'Thank you, your premium has been received.',
  metadata: { memberId: $.data.memberId },
});
